"""Offline authored prediction/evidence labs; three optional precise manipulable models."""
from html import escape
from visuals import render_svg
import json
from interactive_models import model_html as additional_model_html, CSS as ADDITIONAL_CSS, JS as ADDITIONAL_JS

def e(x): return escape(str(x),quote=True)
def safe_json(x): return json.dumps(x,ensure_ascii=False).replace('</','<\\/').replace('\u2028','\\u2028').replace('\u2029','\\u2029')

CSS=r'''
.lab-jump{display:inline-flex;align-items:center;min-height:44px;padding:8px 13px;margin:6px 0 12px;border:2px solid var(--scaffold-border);border-radius:8px;background:var(--scaffold-bg);font-weight:700;color:#153b5a}.science-lab{margin:18px 0;padding:18px;border:3px solid var(--scaffold-border);border-radius:12px;background:#f8fafc}.science-lab h3{margin:0 0 10px;font-size:1.3rem}.science-lab p{font-size:1rem;line-height:1.5}.lab-controls,.lab-choice-list,.lab-model-controls{display:flex;gap:9px;flex-wrap:wrap;margin:12px 0}.lab-choice-list{display:grid}.science-lab button{min-height:44px;box-shadow:none;font-size:1rem;line-height:1.35;padding:10px 13px}.lab-choice{background:#fff;color:var(--text);border:2px solid #94a3b8;text-align:left}.lab-choice[aria-pressed=true]{background:var(--ido-bg);border-color:var(--ido-border)}.science-lab button:disabled{opacity:.55;cursor:default}.lab-feedback{background:white;border-left:5px solid var(--scaffold-border);padding:12px}.lab-feedback[data-result=correct]{border-color:#15803d}.lab-feedback[data-result=incorrect]{border-color:#b45309}.lab-evidence .science-figure{margin-bottom:8px}.lab-evidence.show-evidence svg{animation:lab-reveal .4s ease-out both}.science-lab.is-paused .lab-evidence svg{animation-play-state:paused}.lab-status{font-weight:700;color:#334155}.lab-model{background:white;border:1px solid #cbd5e1;border-radius:10px;padding:12px;margin:16px 0}.lab-model svg{width:100%;height:auto;display:block;background:white}.lab-model label{display:block;font-weight:700}.lab-model input[type=range]{width:100%;min-height:44px}.lab-model-output{font-weight:700;padding:8px;background:#eff6ff}.lab-animation-note{font-size:.86rem!important;color:#475569}.lab-complete{font-weight:700;padding:12px;background:#ecfdf5}.lab-model-controls button[aria-pressed=true]{background:var(--ido-bg);color:var(--text);border:2px solid var(--ido-border)}.lab-marker{transition:cx .7s ease,cy .7s ease}.lab-shadow{transition:y .5s ease,height .5s ease}.lab-rate-bar{transition:width .5s ease}.science-lab.is-paused .lab-marker,.science-lab.is-paused .lab-shadow,.science-lab.is-paused .lab-rate-bar{transition:none}.science-lab [hidden]{display:none!important}@keyframes lab-reveal{from{opacity:.25}to{opacity:1}}@media(prefers-reduced-motion:reduce){.lab-evidence.show-evidence svg{animation:none}.lab-marker,.lab-shadow,.lab-rate-bar{transition:none!important}}@media(max-width:700px){.science-lab{padding:12px}.lab-model{overflow:auto}.lab-model svg{min-width:600px}.lab-controls button{flex:1 1 120px}}@media print{.science-lab{display:none!important}}
'''

def model_html(spec,uid):
 mode=spec.get('mode')
 if mode=='shadow':
  g=dict(spec['geometry']); g['objectHeightCm']=g.get('objectHeightCm',g.get('objectWidthCm')); distances=g['distancesCm']; lo=min(distances);hi=max(distances);start=distances[0]
  return f'''<div class="lab-model" data-model="shadow" data-geometry="{e(json.dumps(g))}"><h4>Shadow-size model</h4><p>Change source-to-object distance. The source and screen stay fixed. This is ideal point-source geometry, not practical measurements.</p><label for="{uid}-distance">Source to object: <span data-shadow-distance></span> cm</label><input id="{uid}-distance" data-shadow-slider type="range" min="{lo}" max="{hi}" value="{start}" step="1"><svg font-family="Segoe UI, Arial, sans-serif" fill="#1f2937" viewBox="0 0 1000 470" role="img" aria-label="Ideal point source, movable opaque object and fixed screen. Shadow size changes with object distance."><text x="30" y="40" font-size="26" fill="#1f2937">Source and screen fixed; heights shown to one scale</text><circle cx="65" cy="245" r="13" fill="#f59e0b"/><text x="25" y="425" font-size="23">Source</text><line x1="890" y1="75" x2="890" y2="405" stroke="#475569" stroke-width="4"/><rect data-shadow-rect class="lab-shadow" x="878" y="160" width="24" height="170" fill="#334155"/><line data-shadow-ray="upper" x1="65" y1="245" x2="890" y2="160" stroke="#d97706" stroke-width="4"/><line data-shadow-ray="lower" x1="65" y1="245" x2="890" y2="330" stroke="#d97706" stroke-width="4"/><rect data-shadow-object x="220" y="223" width="12" height="44" fill="#111827"/><text data-shadow-object-label x="220" y="295" font-size="23">Object</text><text x="840" y="435" font-size="23">Screen</text><text x="410" y="455" font-size="22">Distances are labelled in cm; model not life-size.</text></svg><p class="lab-model-output" data-shadow-output aria-live="polite"></p><p class="lab-animation-note">The object stays the same height. Ray lines show limiting paths from an ideal point source; this model omits the fuzzy edges of a real torch.</p></div>'''
 if mode=='circulation':
  return '''<div class="lab-model" data-model="circulation"><h4>Trace the double circulation</h4><p>Move the marker one stop at a time. Read what changes at each stop.</p><svg font-family="Segoe UI, Arial, sans-serif" fill="#1f2937" viewBox="0 0 1000 500" role="img" aria-label="Schematic loop: body to right heart to lungs to left heart and back to body. Positions are not anatomical."><defs><marker id="circulation-lab-arrow" markerWidth="8" markerHeight="8" refX="7" refY="4" orient="auto"><path d="M0 0 L8 4 L0 8 Z" fill="#475569"/></marker></defs><line x1="245" y1="195" x2="310" y2="145" stroke="#475569" stroke-width="6" marker-end="url(#circulation-lab-arrow)"/><line x1="545" y1="100" x2="615" y2="100" stroke="#475569" stroke-width="6" marker-end="url(#circulation-lab-arrow)"/><line x1="780" y1="145" x2="810" y2="235" stroke="#475569" stroke-width="6" marker-end="url(#circulation-lab-arrow)"/><line x1="755" y1="325" x2="640" y2="395" stroke="#475569" stroke-width="6" marker-end="url(#circulation-lab-arrow)"/><line x1="390" y1="405" x2="195" y2="285" stroke="#475569" stroke-width="6" marker-end="url(#circulation-lab-arrow)"/><rect x="45" y="195" width="225" height="90" rx="12" fill="#e0f2fe" stroke="#1f2937"/><text x="157" y="247" text-anchor="middle" font-size="26">BODY</text><rect x="295" y="55" width="250" height="90" rx="12" fill="#eff6ff" stroke="#1f2937"/><text x="420" y="107" text-anchor="middle" font-size="26">RIGHT HEART</text><rect x="615" y="55" width="245" height="90" rx="12" fill="#f1f5f9" stroke="#1f2937"/><text x="737" y="107" text-anchor="middle" font-size="26">LUNGS</text><rect x="675" y="235" width="270" height="90" rx="12" fill="#fff1f2" stroke="#1f2937"/><text x="810" y="287" text-anchor="middle" font-size="26">LEFT HEART</text><rect x="390" y="365" width="250" height="80" rx="12" fill="#e0f2fe" stroke="#1f2937"/><text x="515" y="412" text-anchor="middle" font-size="25">BACK TO BODY</text><circle class="lab-marker" data-circulation-marker cx="157" cy="177" r="13" fill="#f59e0b" stroke="#1f2937" stroke-width="3"/></svg><div class="lab-model-controls"><button type="button" data-circulation-next>Next stop</button><button type="button" data-circulation-reset>Restart loop</button></div><p data-circulation-output class="lab-model-output" aria-live="polite"></p><p class="lab-animation-note">Positions and travel time are schematic. The marker represents a tracing point, not blood colour or a whole packet of nutrients.</p></div>'''
 if mode=='rates':
  rows=spec['populations']; assert 2<=len(rows)<=4
  bars=[]
  for i,r in enumerate(rows):
   y=80+i*100
   bars.append(f'<text x="15" y="{y+16}" font-size="24">{e(r["name"])}</text><text x="15" y="{y+46}" font-size="20">Population {r["population"]:,}</text><rect class="lab-rate-bar" data-rate-bar="{i}" x="310" y="{y-14}" width="0" height="42" fill="#7a5c9e"/><text data-rate-label="{i}" x="315" y="{y+56}" font-size="22"></text>')
  return '<div class="lab-model" data-model="rates" data-populations="'+e(json.dumps(rows))+'"><h4>Counts or population-adjusted rates?</h4><p>Constructed comparison data, same reporting period and case definition. Keep the population denominators visible.</p><div class="lab-model-controls"><button type="button" data-rate-view="count" aria-pressed="true">Case counts</button><button type="button" data-rate-view="rate" aria-pressed="false">Cases per 1,000 people</button></div><svg font-family="Segoe UI, Arial, sans-serif" fill="#1f2937" viewBox="0 0 1000 '+str(120+100*len(rows))+'" role="img" aria-label="Constructed district comparison. Toggle case counts or rates per one thousand people."><text data-rate-title x="310" y="35" font-size="25">Case counts</text><line x1="310" y1="50" x2="310" y2="'+str(100*len(rows)+90)+'" stroke="#1f2937" stroke-width="3"/>'+''.join(bars)+'</svg><p data-rate-output class="lab-model-output" aria-live="polite"></p><p class="lab-animation-note">Both views start at zero and use a common scale within that view. The scale changes between counts and rates; bar movement is a chart transition, not changing disease cases.</p></div>'
 return additional_model_html(spec,uid)

def panel_html(spec,uid):
 steps=spec['steps'];assert len(steps)>=2
 chunks=[]
 for i,s in enumerate(steps):
  choices=s['choices'];assert any(c['correct'] for c in choices)
  vh=render_svg(s['visual'],uid+f'-step{i}') if s.get('visual') else ''
  chunks.append(f'<section data-lab-step="{i}" tabindex="-1" aria-label="{e(s["question"])}"'+(' hidden' if i else '')+'><p class="lab-status">Decision '+str(i+1)+' of '+str(len(steps))+'</p><p class="science-prompt">'+e(s['question'])+'</p><div class="lab-choice-list" role="group" aria-label="'+e(s['question'])+'">'+''.join(f'<button type="button" class="lab-choice" data-lab-choice="{j}" data-correct="{str(c["correct"]).lower()}" data-feedback="{e(c["feedback"])}" aria-pressed="false">{e(c["text"])}</button>' for j,c in enumerate(choices))+'</div><button type="button" data-lab-test disabled>Test against the evidence</button><div data-lab-feedback class="lab-feedback" role="status" aria-live="polite" hidden></div><div data-lab-evidence class="lab-evidence" hidden><figure class="science-figure">'+vh+'<figcaption>'+e(s.get('visual',{}).get('title','Evidence model'))+'</figcaption></figure><p>'+e(s['explanation'])+'</p></div></section>')
 return f'<section class="science-lab" id="{uid}" tabindex="-1" data-science-lab aria-labelledby="{uid}-title"><h3 id="{uid}-title">{e(spec["title"])}</h3><p>{e(spec["intro"])}</p>'+model_html(spec,uid)+''.join(chunks)+f'<div class="lab-controls"><button type="button" data-lab-next disabled>Next decision</button><button type="button" data-lab-pause aria-pressed="false">Pause model</button><button type="button" data-lab-reset>Reset investigation</button></div><p data-lab-complete class="lab-complete" hidden>All decisions checked. Explain one choice using the evidence, then save your work.</p><input type="hidden" data-note data-lab-record aria-label="{e(spec["title"])}" value="Investigation not started"><p class="lab-animation-note">Choose, test, then explain together. Evidence diagrams appear only after your test. Diagram transitions explain the model; they do not represent real elapsed time. Use Pause model to stop transitions and model controls, or your device’s reduced-motion setting. The printed We do activity provides the paper route.</p><noscript><p>The interactive controls need JavaScript. Use the evidence and questions on this slide and in the pupil booklet, then check the teacher guidance.</p></noscript></section>'

JS=r'''
(function(){
'use strict';
document.querySelectorAll('[data-science-lab]').forEach(lab=>{
 const steps=Array.from(lab.querySelectorAll('[data-lab-step]'));let current=0;let paused=false;const tested=new Set();const record=lab.querySelector('[data-lab-record]');
 const next=lab.querySelector('[data-lab-next]'),pause=lab.querySelector('[data-lab-pause]');
 function save(){record.value=steps.map((s,i)=>{const selected=s.querySelector('[data-lab-choice][aria-pressed=true]');return 'Decision '+(i+1)+': '+s.querySelector('.science-prompt').textContent+'\nChoice: '+(selected?selected.textContent:'Not chosen')+'\n'+(tested.has(i)?s.querySelector('[data-lab-feedback]').textContent:'Not tested');}).join('\n\n');}
 function show(i){current=i;steps.forEach((s,k)=>s.hidden=k!==i);next.disabled=!tested.has(i)||i===steps.length-1;next.textContent=i===steps.length-1?'Final decision':'Next decision';lab.querySelector('[data-lab-complete]').hidden=tested.size!==steps.length;}
 const disabledBeforePause=new Map();
 function setPaused(value){const controls=lab.querySelectorAll('.lab-model button,.lab-model input');if(value&&!paused){disabledBeforePause.clear();controls.forEach(b=>disabledBeforePause.set(b,b.disabled));}controls.forEach(b=>b.disabled=value?true:(disabledBeforePause.has(b)?disabledBeforePause.get(b):b.disabled));paused=value;lab.classList.toggle('is-paused',value);pause.setAttribute('aria-pressed',String(value));pause.textContent=value?'Resume model':'Pause model';}
 steps.forEach((step,i)=>{
  step.querySelectorAll('[data-lab-choice]').forEach(button=>button.addEventListener('click',()=>{step.querySelectorAll('[data-lab-choice]').forEach(b=>b.setAttribute('aria-pressed',String(b===button)));step.querySelector('[data-lab-test]').disabled=false;step.querySelector('[data-lab-feedback]').hidden=true;step.querySelector('[data-lab-evidence]').hidden=true;step.querySelector('[data-lab-evidence]').classList.remove('show-evidence');tested.delete(i);show(current);save();}));
  step.querySelector('[data-lab-test]').addEventListener('click',()=>{const b=step.querySelector('[data-lab-choice][aria-pressed=true]');if(!b)return;const f=step.querySelector('[data-lab-feedback]');f.textContent=(b.dataset.correct==='true'?'Evidence supports this. ':'Revise your explanation. ')+b.dataset.feedback;f.dataset.result=b.dataset.correct==='true'?'correct':'incorrect';f.hidden=false;const evidence=step.querySelector('[data-lab-evidence]');evidence.hidden=false;evidence.classList.add('show-evidence');tested.add(i);show(i);save();});
 });
 next.addEventListener('click',()=>{if(tested.has(current)&&current<steps.length-1){show(current+1);steps[current].focus();}});
 pause.addEventListener('click',()=>setPaused(!paused));
 const resets=[];
 lab.querySelectorAll('[data-model]').forEach(model=>{
  if(model.dataset.model==='shadow'){
   const g=JSON.parse(model.dataset.geometry),slider=model.querySelector('[data-shadow-slider]');
   function update(){const d=Number(slider.value),width=g.objectHeightCm*g.sourceScreenCm/d;const scale=12;const x=65+825*d/g.sourceScreenCm;const h=width*scale,objectH=g.objectHeightCm*scale;
    model.querySelector('[data-shadow-distance]').textContent=String(d);const rect=model.querySelector('[data-shadow-rect]');rect.setAttribute('y',245-h/2);rect.setAttribute('height',h);
    const obj=model.querySelector('[data-shadow-object]');obj.setAttribute('x',x-6);obj.setAttribute('y',245-objectH/2);obj.setAttribute('height',objectH);model.querySelector('[data-shadow-object-label]').setAttribute('x',Math.min(770,x-30));model.querySelector('[data-shadow-object-label]').setAttribute('y',245+objectH/2+35);
    model.querySelector('[data-shadow-ray="upper"]').setAttribute('y2',245-h/2);model.querySelector('[data-shadow-ray="lower"]').setAttribute('y2',245+h/2);
    model.querySelector('[data-shadow-output]').textContent='Object height '+g.objectHeightCm+' cm × source-to-screen '+g.sourceScreenCm+' cm ÷ source-to-object '+d+' cm = shadow height '+Number(width.toFixed(2))+' cm (ideal model).';
   }slider.addEventListener('input',update);slider.addEventListener('change',update);resets.push(()=>{slider.value=String(g.distancesCm[0]);update();});update();
  }
  if(model.dataset.model==='circulation'){
   let stop=0;const points=[[157,177],[420,36],[737,36],[810,216],[515,346]];
   const texts=['BODY: cells use oxygen; blood returning from the body has less oxygen and more carbon dioxide.','RIGHT HEART: receives blood from the body and pumps it to the lungs. It does not add oxygen.','LUNGS: oxygen moves into the blood; carbon dioxide moves out of it.','LEFT HEART: receives blood from the lungs and pumps it to the body.','BACK TO BODY: oxygen is delivered to cells. The route continues around the double circulation.'];
   function update(){const marker=model.querySelector('[data-circulation-marker]');marker.setAttribute('cx',points[stop][0]);marker.setAttribute('cy',points[stop][1]);model.querySelector('[data-circulation-output]').textContent=(stop+1)+'/5 · '+texts[stop];}
   model.querySelector('[data-circulation-next]').addEventListener('click',()=>{stop=(stop+1)%points.length;update();});model.querySelector('[data-circulation-reset]').addEventListener('click',()=>{stop=0;update();});resets.push(()=>{stop=0;update();});update();
  }
  if(model.dataset.model==='rates'){
   const rows=JSON.parse(model.dataset.populations);
   function update(mode){const rates=mode==='rate',values=rows.map(r=>rates?r.cases/r.population*1000:r.cases),max=Math.max(...values,1);model.querySelectorAll('[data-rate-view]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.rateView===mode)));model.querySelector('[data-rate-title]').textContent=rates?'Cases per 1,000 people':'Case counts';rows.forEach((r,i)=>{model.querySelector('[data-rate-bar="'+i+'"]').setAttribute('width',String(values[i]/max*620));model.querySelector('[data-rate-label="'+i+'"]').textContent=Number(values[i].toFixed(2))+(rates?' per 1,000':' cases');});model.querySelector('[data-rate-output]').textContent=rates?rows.map(r=>r.name+': '+r.cases+' ÷ '+r.population+' × 1,000 = '+Number((r.cases/r.population*1000).toFixed(2))+' per 1,000').join(' · '):rows.map(r=>r.name+': '+r.cases+' cases among '+r.population+' people').join(' · ');}
   model.querySelectorAll('[data-rate-view]').forEach(b=>b.addEventListener('click',()=>update(b.dataset.rateView)));resets.push(()=>update('count'));update('count');
  }
 });
 lab.querySelector('[data-lab-reset]').addEventListener('click',()=>{steps.forEach(step=>{step.querySelectorAll('[data-lab-choice]').forEach(b=>b.setAttribute('aria-pressed','false'));step.querySelector('[data-lab-test]').disabled=true;step.querySelector('[data-lab-feedback]').hidden=true;step.querySelector('[data-lab-evidence]').hidden=true;step.querySelector('[data-lab-evidence]').classList.remove('show-evidence');});tested.clear();setPaused(false);resets.forEach(f=>f());show(0);record.value='Investigation reset; no current decisions recorded';});
 document.querySelectorAll('[data-action="pause"]').forEach(b=>b.addEventListener('click',()=>setPaused(true)));
 document.addEventListener('classic-slide-change',()=>{if(tested.size>0&&!lab.closest('.slide').classList.contains('active'))setPaused(true);});
 document.addEventListener('visibilitychange',()=>{if(document.hidden)setPaused(true);});
 show(0);
});
}());
'''

CSS += ADDITIONAL_CSS
JS += ADDITIONAL_JS
